import {escapeHTML as e} from './model.js';
import {avatar,icon,pageHeading,badge,empty} from './ui.js';
import {renderMap} from './map.js';
export const ROUTES=[['mapa','Atlas do mundo','map'],['personagens','Personagens','people'],['capitulos','Capítulos','book'],['compendio','Compêndio','spark'],['faccoes','Facções','flag'],['tramas','Tramas e mistérios','pin'],['campeonato','Campeonato','sword'],['universo','Universo e backups','settings']];
const locationName=(c,id)=>c.locations.find(l=>l.id===id)?.name||'Local desconhecido';
const button=(action,label,primary=false)=>`<button class="${primary?'primary':''}" data-action="${action}">${icon('plus')}${label}</button>`;
export function inspector(c,id) {
 const ch=c.characters.find(v=>v.id===id)||c.characters[0];
 if(!ch)return `<aside class="inspector">${empty('O elenco ainda está vazio','Crie seu primeiro personagem.','<button data-action="new-character">Criar personagem</button>')}</aside>`;
 return `<aside class="inspector"><div class="inspector-top"><span class="eyebrow">EM FOCO</span><button class="text-button" data-edit-character="${e(ch.id)}">Editar ↗</button></div><button class="portrait-button" data-open-character="${e(ch.id)}" aria-label="Ampliar ficha de ${e(ch.name)}">${avatar(ch,'portrait')}<div class="portrait-shade"></div><div class="portrait-caption"><small>${e(ch.role)}</small><h2>${e(ch.name)}</h2></div></button><div class="inspector-body"><div class="location-line">${icon('pin')} ${e(locationName(c,ch.locationId))}</div><div class="rank-row"><span>RANK</span><strong>${e(ch.rank)}</strong></div><h3>O que sabemos</h3><p class="summary-preview">${e(ch.summary)}</p><h3>Vínculos</h3><p>${e(ch.relations)}</p><button class="wide" data-open-character="${e(ch.id)}">Abrir ficha completa ${icon('arrow')}</button></div></aside>`;
}
export function atlas(c,ui) {
 return `${pageHeading('A CAMPANHA EM MOVIMENTO','Atlas do mundo','Cada lugar guarda uma história. Cada personagem, um novo caminho.',button('new-character','Novo personagem',true))}
 <div class="campaign-strip"><div>${icon('moon')} <strong>${e(c.name)}</strong><span class="muted">${e(c.subtitle)}</span></div><span class="date-pill">${e(c.day)}</span></div>
 <div class="atlas-layout"><div class="atlas-left"><section class="atlas-panel">${renderMap(c,ui.mapId,ui.selectedId,ui)}</section><div class="stats-grid"><a href="#personagens"><span>${icon('people')} PERSONAGENS</span><strong>${c.characters.length.toString().padStart(2,'0')}</strong><small>Vozes deste universo</small></a><a href="#capitulos"><span>${icon('book')} CAPÍTULOS</span><strong>${c.chapters.filter(v=>v.status==='Concluído').length.toString().padStart(2,'0')}<em> / ${c.chapters.length.toString().padStart(2,'0')}</em></strong><small>Concluídos / no arquivo</small></a><a href="#tramas"><span>${icon('spark')} TRAMAS ABERTAS</span><strong>${c.threads.filter(v=>v.status!=='Resolvido').length.toString().padStart(2,'0')}</strong><small>Histórias por desvendar</small></a></div></div>${inspector(c,ui.selectedId)}</div>
 <div class="below-grid"><section class="panel next-chapter"><div class="eyebrow">NA PRÓXIMA PÁGINA</div><h2>${e(c.chapters.find(v=>v.status==='Rascunho')?.title||'O próximo capítulo é seu')}</h2><p>${e(c.chapters.find(v=>v.status==='Rascunho')?.body.slice(0,170)||'Guarde ideias, encontros e acontecimentos para continuar sua campanha.')}${c.chapters.some(v=>v.status==='Rascunho')?'…':''}</p><a href="#capitulos">Continuar a crônica ${icon('arrow')}</a></section><section class="panel"><div class="section-line"><h2>Nos arquivos do reino</h2><span class="muted">REGISTROS RECENTES</span></div>${(c.history||[{description:'Compêndio organizado · Dia 26 da Lua Pálida',date:c.updatedAt}]).slice(-3).reverse().map(h=>`<div class="history-row"><span class="history-dot"></span><div>${e(h.description)}<small>${new Date(h.date).toLocaleString('pt-BR')}</small></div></div>`).join('')}</section></div>`;
}
export function characterView(c,query='') {
 const q=query.toLocaleLowerCase('pt-BR');const chars=c.characters.filter(ch=>[ch.name,ch.role,ch.faction,locationName(c,ch.locationId),ch.summary].join(' ').toLocaleLowerCase('pt-BR').includes(q));
 return `${pageHeading('ROSTOS, ESCOLHAS E VÍNCULOS','Personagens','Fichas vivas para quem habita o seu mundo.',button('new-character','Novo personagem',true))}<div class="list-toolbar"><label class="search-box">${icon('search')}<input id="filter" type="search" placeholder="Buscar nome, função, facção ou local…" value="${e(query)}" aria-label="Buscar personagens"></label><span class="muted">${chars.length} personagens · ${c.characters.filter(ch=>ch.image).length} com imagem</span></div><div class="character-grid">${chars.map(ch=>`<article class="character-card"><button class="character-cover" data-open-character="${e(ch.id)}">${avatar(ch,'card-portrait')}<span class="card-rank">${e(ch.rank)}</span></button><div class="card-content"><small>${e(ch.role)}</small><h2><button class="text-button" data-open-character="${e(ch.id)}">${e(ch.name)}</button></h2><p class="location-line">${icon('pin')}${e(locationName(c,ch.locationId))}</p><p class="card-summary">${e(ch.summary)}</p><div class="card-footer"><span>${e(ch.faction)}</span><button class="text-button" data-edit-character="${e(ch.id)}">Editar ↗</button></div></div></article>`).join('')}</div>${chars.length?'':empty('Nenhum personagem encontrado','Tente outra busca ou adicione um novo integrante.')}`;
}
export function chapterView(c,selectedId) {
 const ch=c.chapters.find(v=>v.id===selectedId)||c.chapters.at(-1);
 return `${pageHeading('O ARQUIVO DA CAMPANHA','Capítulos','Escreva, revise e preserve cada parte da sua história.',button('new-chapter','Novo capítulo',true))}<div class="chapter-layout"><aside class="chapter-index"><div class="eyebrow">A CRÔNICA · ${c.chapters.length} CAPÍTULOS</div>${c.chapters.map((v,i)=>`<button class="chapter-item ${v.id===ch?.id?'active':''}" data-chapter="${e(v.id)}"><span class="chapter-number">${String(i+1).padStart(2,'0')}</span><div><strong>${e(v.title)}</strong><small>${e(v.period)}</small>${badge(v.status)}</div></button>`).join('')}</aside>${ch?`<article class="chapter-paper"><div class="section-line"><span class="eyebrow">${e(ch.period)}</span><div><button data-edit-chapter="${e(ch.id)}">Editar texto</button><button class="quiet" data-export-chapter="${e(ch.id)}" title="Baixar capítulo em Markdown">↓ .md</button></div></div><h2>${e(ch.title)}</h2>${badge(ch.status)}<div class="prose">${e(ch.body)}</div><div class="linked-characters"><div class="eyebrow">PERSONAGENS DESTE CAPÍTULO</div><div>${ch.characterIds.map(id=>{const char=c.characters.find(v=>v.id===id);return char?`<button class="character-chip" data-open-character="${e(id)}">${avatar(char)}${e(char.name)}</button>`:'';}).join('')||'<p class="muted">Nenhum vínculo registrado.</p>'}</div></div></article>`:empty('Uma história por escrever','Crie o primeiro capítulo para começar o arquivo.')}</div>`;
}
export function recordView(c,key,query='') {
 const config={lore:['AS LEIS DO SEU UNIVERSO','Compêndio','O cânone, as regras e as memórias que sustentam a campanha.','Novo registro'],factions:['O EQUILÍBRIO DO PODER','Facções','Instituições, alianças e forças em disputa.','Nova facção'],threads:['NEM TUDO FOI REVELADO','Tramas e mistérios','Acompanhe os fios soltos, os riscos e as perguntas em aberto.','Nova trama']}[key];
 const rows=c[key].filter(v=>(v.title+' '+v.body+' '+v.status).toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR')));
 return `${pageHeading(...config.slice(0,3),button(`new-${key}`,config[3],true))}<div class="list-toolbar"><label class="search-box">${icon('search')}<input id="filter" type="search" placeholder="Buscar nos registros…" value="${e(query)}" aria-label="Buscar registros"></label><span class="muted">${rows.length} registros</span></div><div class="record-grid">${rows.map(v=>`<article class="panel record-card"><div class="section-line">${badge(v.status)}<button class="text-button" data-edit-record="${key}:${e(v.id)}">Editar ↗</button></div><h2>${e(v.title)}</h2><div class="prose">${e(v.body)}</div></article>`).join('')}</div>${rows.length?'':empty('Nenhum registro por aqui','Adicione um registro ou tente outra busca.')}`;
}
export function tournamentView(c) {
 const name=id=>c.characters.find(ch=>ch.id===id)?.name||'A definir';
 return `${pageHeading('O CAMPO DO LEÃO','Campeonato de Batalhas','Planejamento separado do cânone: registre confrontos quando forem definidos.',button('new-match','Novo confronto',true))}<div class="tournament-layout"><section class="panel"><div class="section-line"><span class="eyebrow">REGULAMENTO E PLANEJAMENTO</span><button class="text-button" data-action="edit-rules">Editar ↗</button></div><div class="prose">${e(c.tournament.rules||'Defina o regulamento deste campeonato.')}</div><p class="muted">Resultados são registrados manualmente. Os ranks não geram resultados automáticos.</p></section><section><div class="section-line"><h2>Confrontos</h2><span class="muted">${c.tournament.matches.length} REGISTRADOS</span></div>${c.tournament.matches.map(m=>`<article class="panel match"><div class="section-line"><span class="eyebrow">${e(m.round)}</span><button class="text-button" data-match="${e(m.id)}">Editar ↗</button></div><div class="versus"><strong>${e(name(m.a))}</strong><span>×</span><strong>${e(name(m.b))}</strong></div>${badge(m.winner?(m.winner==='empate'?'Empate':`Vitória: ${name(m.winner)}`):'Aguardando resultado')}<p>${e(m.notes)}</p></article>`).join('')||empty('As chaves ainda estão abertas','Nenhuma luta foi inventada. Adicione confrontos conforme o Conselho decidir.')}</section></div>`;
}
export function settingsView(c,state) {
 return `${pageHeading('MUNDOS QUE CONTINUAM','Universo e backups','Sua campanha é sua. Leve os arquivos com você, crie novos mundos e ajuste o atlas.')}<div class="settings-grid"><section class="panel"><h2>Esta campanha</h2><p class="muted">${e(c.name)} · ${e(c.day)}</p><button data-action="edit-campaign">Editar nome e calendário</button><hr><h3>Outras histórias</h3><p>Campanhas têm mapas, personagens e arquivos independentes.</p><button data-action="new-campaign">${icon('plus')} Nova campanha</button><p class="muted">${state.campaigns.length} campanha(s) neste navegador.</p><button class="text-button danger-text" data-action="delete-campaign">Excluir campanha atual</button></section><section class="panel"><h2>Salvar e levar com você</h2><p>Os dados ficam no armazenamento deste navegador. Acesse sempre pelo mesmo endereço e perfil. Não há sincronização automática entre dispositivos.</p><div class="button-row"><button class="primary" data-action="backup">↓ Exportar backup completo</button><button data-action="import">↑ Importar backup</button></div><p class="muted">JSON com todas as campanhas, imagens e posições. A importação substitui o arquivo atual após validação.</p><button data-action="persistent">Solicitar armazenamento persistente</button><button class="text-button" data-action="restore">Restaurar gravação anterior</button><p id="storage-info" class="muted"></p></section><section class="panel"><div class="section-line"><h2>Mapas deste mundo</h2><button data-action="new-map">${icon('plus')} Mapa</button></div>${c.maps.map(m=>`<div class="map-list-item"><img src="${e(m.image)}" alt="${e(m.name)}"><div><strong>${e(m.name)}</strong><small>${c.locations.filter(l=>l.mapId===m.id).length} localidades</small></div><button class="text-button" data-edit-map="${e(m.id)}">Editar</button></div>`).join('')||'<p>Adicione a primeira imagem de mapa.</p>'}<p class="muted">Novos mapas aceitam marcadores livres. As localidades são pontos editáveis; não há polígonos automáticos.</p></section><section class="panel"><div class="section-line"><h2>Localidades</h2><button data-action="new-location">${icon('plus')} Local</button></div><div class="location-list">${c.locations.map(l=>`<button data-edit-location="${e(l.id)}"><span>${icon('pin')} ${e(l.name)}</span><small>${l.x.toFixed(1)}%, ${l.y.toFixed(1)}%</small></button>`).join('')||'<p>Crie locais depois de adicionar um mapa.</p>'}</div></section><section class="panel linux-panel"><div>${icon('settings')}<h2>No seu Linux</h2><p>Uma aplicação leve, sem instalação de pacotes JavaScript. Baixe o projeto, extraia e execute <code>python3 serve.py</code>. Abra <code>http://127.0.0.1:8080</code> e importe seu backup para continuar.</p></div><a class="button" href="./caldris-linux.zip" download>↓ Código + imagens + guia Linux</a></section></div>`;
}
